import{_ as d,o,c,a2 as t}from"./chunks/framework.Bg-Zxr5O.js";const R=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-zh/Matrix-READ-and-WRITE-Commands.md","filePath":"manual-zh/Matrix-READ-and-WRITE-Commands.md","lastUpdated":1785684581000}'),a={name:"manual-zh/Matrix-READ-and-WRITE-Commands.md"};function r(_,e,i,m,n,l){return o(),c("div",null,[...e[0]||(e[0]=[t('<h4 id="_16-4-8-read-和-write-命令" tabindex="-1">16.4.8 <code>READ</code> 和 <code>WRITE</code> 命令 <a class="header-anchor" href="#_16-4-8-read-和-write-命令" aria-label="Permalink to &quot;16.4.8 `READ` 和 `WRITE` 命令&quot;">​</a></h4><p><code>READ</code> 和 <code>WRITE</code> 命令与文本文件进行矩阵输入输出。它们共享以下语法以指定数据如何在输入行之间划分：</p><pre><code>/FIELD=_first_ TO _last_ [BY _width_]\n[/FORMAT=_format_]\n</code></pre><p>两个命令都需要 <code>FIELD</code> 子命令。它指定数据在文件每一行上所占的列范围，从 first 到 last（含）。最左边的列是第 1 列。列必须是字面数字，而不是表达式。要使用整行（即使可能非常长），指定一个列范围，例如 <code>1 TO 100000</code>。</p><p><code>FORMAT</code> 子命令对于数值矩阵是可选的。对于字符串矩阵的输入和输出，指定 <code>A</code> 格式。除 <code>FORMAT</code> 外，<code>FIELD</code> 上的可选 <code>BY</code> 指定确定每个文本行含义：</p><ul><li>既无 <code>BY</code> 也无 <code>FORMAT</code> 时，文本文件中的数字是以空格或逗号分隔的 <code>F</code> 格式。对于 <code>WRITE</code>，PSPP 使用准确表示矩阵中数字所需的精度位数。</li><li><code>BY _width_</code> 将输入区域划分为给定 <em>width</em> 的固定宽度字段。输入区域宽度必须是 <em>width</em> 的整数倍。数字以 <code>F _width_.0</code> 格式读取或写入。</li><li><code>FORMAT=&quot;_count_ F&quot;</code> 将输入区域划分为每行 <em>count</em> 个等宽字段。输入区域宽度必须是 <em>count</em> 的整数倍。可以用另一种格式类型替代 <code>F</code>。</li><li><code>FORMAT=F _w_</code>[<code>._d_</code>] 将输入区域划分为宽度为 <em>w</em> 的固定宽度字段。输入区域宽度必须是 <em>w</em> 的整数倍。可以用另一种格式类型替代 <code>F</code>。<code>READ</code> 命令忽略 <em>d</em>。</li><li><code>FORMAT=F</code> 指定格式 <code>F</code> 但不指示字段宽度。可以用另一种格式类型替代 <code>F</code>。<code>WRITE</code> 命令接受这种形式，但除非同时使用 <code>BY</code> 指定字段宽度，否则不起作用。</li></ul><p>如果 <code>BY</code> 和 <code>FORMAT</code> 都指定或隐含字段宽度，则它们必须指示相同的字段宽度。</p><table tabindex="0"><thead><tr><th>• READ 命令</th><th></th><th></th></tr></thead><tbody><tr><td>• WRITE 命令</td><td></td><td></td></tr></tbody></table>',8)])])}const T=d(a,[["render",r]]);export{R as __pageData,T as default};
